//! Token-ID goldens generated by HF tokenizers 0.22.2, through both real loaders.
use super::*;
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};

const TOKENIZER_JSON: &str = include_str!("../tests/fixtures/qwen2-tokenizer.json");
const ORACLE_JSON: &str = include_str!("../tests/fixtures/qwen2-oracle.json");

struct FixtureDir(PathBuf);

impl FixtureDir {
    fn new() -> Self {
        static NEXT: AtomicU64 = AtomicU64::new(0);
        let dir = std::env::temp_dir().join(format!(
            "memra-qwen2-oracle-{}-{}",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        std::fs::create_dir(&dir).unwrap();
        Self(dir)
    }

    fn hf(&self, tokenizer: &str) -> Tokenizer {
        std::fs::write(self.0.join("tokenizer.json"), tokenizer).unwrap();
        let oracle = json::parse(ORACLE_JSON).unwrap();
        let eos = oracle.get("eos_token_id").unwrap().as_u64().unwrap();
        std::fs::write(
            self.0.join("generation_config.json"),
            format!("{{\"eos_token_id\":{eos}}}"),
        )
        .unwrap();
        Tokenizer::from_hf_dir(&self.0).unwrap()
    }
}

impl Drop for FixtureDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn ids(value: &json::Value) -> Vec<u32> {
    value
        .as_arr()
        .unwrap()
        .iter()
        .map(|v| u32::try_from(v.as_u64().unwrap()).unwrap())
        .collect()
}

fn assert_oracle(tok: &Tokenizer) {
    let oracle = json::parse(ORACLE_JSON).unwrap();
    let cases = oracle.get("cases").unwrap().as_arr().unwrap();
    assert_eq!(cases.len(), 39, "oracle coverage must not silently shrink");
    for case in cases {
        let text = case.get("text").unwrap().as_str().unwrap();
        let expected = ids(case.get("ids").unwrap());
        for special in [false, true] {
            let actual = tok.encode(text, special);
            assert_eq!(actual, expected, "text={text:?}, special={special}");
            assert_eq!(tok.decode(&actual), text);
        }
    }
}

#[test]
fn qwen2_hf_token_ids_match_declared_regex_oracle() {
    let dir = FixtureDir::new();
    let tok = dir.hf(TOKENIZER_JSON);
    assert_eq!(tok.pre(), "qwen2");
    assert_oracle(&tok);
}

// Minimal GGUF v3 serialization keeps the same oracle vocabulary and merges while
// exercising the actual GGUF parser/metadata path, not a hand-constructed Tokenizer.
fn put_string(bytes: &mut Vec<u8>, value: &str) {
    bytes.extend_from_slice(&(value.len() as u64).to_le_bytes());
    bytes.extend_from_slice(value.as_bytes());
}

fn put_string_array(bytes: &mut Vec<u8>, key: &str, values: &[String]) {
    put_string(bytes, key);
    bytes.extend_from_slice(&9u32.to_le_bytes()); // ARRAY
    bytes.extend_from_slice(&8u32.to_le_bytes()); // STRING element type
    bytes.extend_from_slice(&(values.len() as u64).to_le_bytes());
    for value in values {
        put_string(bytes, value);
    }
}

#[test]
fn qwen2_gguf_token_ids_match_declared_regex_oracle() {
    let dir = FixtureDir::new();
    let parsed = json::parse(TOKENIZER_JSON).unwrap();
    let model = parsed.get("model").unwrap();
    let vocab = model.get("vocab").unwrap().as_obj().unwrap();
    let mut tokens = vec![String::new(); vocab.len()];
    for (token, id) in vocab {
        tokens[id.as_u64().unwrap() as usize] = token.clone();
    }
    let merges: Vec<String> = model
        .get("merges")
        .unwrap()
        .as_arr()
        .unwrap()
        .iter()
        .map(|v| {
            let pair = v.as_arr().unwrap();
            format!(
                "{} {}",
                pair[0].as_str().unwrap(),
                pair[1].as_str().unwrap()
            )
        })
        .collect();
    let mut bytes = b"GGUF".to_vec();
    bytes.extend_from_slice(&3u32.to_le_bytes());
    bytes.extend_from_slice(&0u64.to_le_bytes()); // no model tensors needed
    bytes.extend_from_slice(&5u64.to_le_bytes()); // metadata entries
    for (key, value) in [
        ("tokenizer.ggml.model", "gpt2"),
        ("tokenizer.ggml.pre", "qwen2"),
    ] {
        put_string(&mut bytes, key);
        bytes.extend_from_slice(&8u32.to_le_bytes());
        put_string(&mut bytes, value);
    }
    put_string_array(&mut bytes, "tokenizer.ggml.tokens", &tokens);
    put_string_array(&mut bytes, "tokenizer.ggml.merges", &merges);
    put_string(&mut bytes, "tokenizer.ggml.eos_token_id");
    bytes.extend_from_slice(&4u32.to_le_bytes()); // UINT32
    let oracle = json::parse(ORACLE_JSON).unwrap();
    let eos = oracle.get("eos_token_id").unwrap().as_u64().unwrap() as u32;
    bytes.extend_from_slice(&eos.to_le_bytes());
    bytes.resize(bytes.len().div_ceil(32) * 32, 0);
    let path = dir.0.join("tokenizer.gguf");
    std::fs::write(&path, bytes).unwrap();
    let gguf = GgufFile::open(&path).unwrap();
    let tok = Tokenizer::from_gguf(&gguf).unwrap();
    assert_eq!(tok.pre(), "qwen2");
    assert_oracle(&tok);
}

#[test]
fn qwen35_retains_its_combining_mark_merge() {
    let dir = FixtureDir::new();
    let fixture = TOKENIZER_JSON.replace(
        &format!("{QWEN2_PRETOKENIZE_REGEX:?}"),
        &format!("{QWEN35_PRETOKENIZE_REGEX:?}"),
    );
    assert_ne!(fixture, TOKENIZER_JSON);
    let tok = dir.hf(&fixture);
    assert_eq!(tok.pre(), "qwen35");
    let oracle = json::parse(ORACLE_JSON).unwrap();
    let expected = ids(oracle.get("qwen35_combining_ids").unwrap());
    assert_eq!(tok.encode("e\u{301}", false), expected);
}
